if(b.role==='magnet'){let m=p.bend,origin=b.x<330?36:348,local=b.x-origin;if(m.focus===null)m.focus=Math.max(70,Math.min(206,local));m.polarity*=-1;m.pulse=cfg.bendDuration;for(let k=1;k<24;k++){let distance=Math.abs(k*11.5-local);m.nodes[k].load=Math.max(m.nodes[k].load,Math.max(0,1-distance/cfg.bendWidth))}let center=b.x<330?174:486;s.magnetEnergy+=cfg.magnetGain+cfg.magnetCenter*Math.max(0,1-Math.abs(b.x-center)/106);if(s.magnetEnergy>=100){if(assembleScrapBoard(b))s.magnetEnergy=0}return false}
if(b.role==='spring'){if(s.lastHit!==null&&time-s.lastHit<=cfg.springComboWindow)s.boost=cfg.springComboDuration;s.lastHit=time;fraction=cfg.springBase/100+cfg.springBonus/100*Math.min(1,(s.impactSpeed/650)**2);flash('spring',[])}
