function drawLeadDebris(b){ctx.save();let origin=b.x<330?36:348;ctx.beginPath();ctx.rect(origin,76,276,1081);ctx.clip();for(const d of b.special.debris){ctx.save();ctx.translate(d.x,d.y);ctx.rotate(d.angle);prepareDebris(d);ctx.fillStyle=Number.isInteger(d.boardIndex)?themePalettes[visualTheme].boards[d.boardIndex]:d.color;if(d.cachedPath)ctx.fill(d.cachedPath);else{ctx.beginPath();for(const r of d.runs)ctx.rect(r.x,r.y,r.w,2.05);ctx.fill()}ctx.restore()}ctx.restore();}

function requestDebrisBreak(d,x,y,speed){if(d.points.length<cfg.debrisBreakSize||(d.generation||0)>=cfg.debrisBreakDepth||d.breakCooldown>0)return;if(!d.breakRequest||speed>d.breakRequest.speed)d.breakRequest={x,y,speed};}
function splitLeadDebris(b){let result=[];for(const d of b.special.debris){if(!d.breakRequest){result.push(d);continue}let hit=d.breakRequest;delete d.breakRequest;let c=Math.cos(d.angle),s=Math.sin(d.angle),hx=(hit.x-d.x)*c+(hit.y-d.y)*s,hy=-(hit.x-d.x)*s+(hit.y-d.y)*c;let angle=Math.atan2(-hy,-hx)+Math.PI/2+(Math.random()-.5)*.5,nx=Math.cos(angle),ny=Math.sin(angle);let values=d.points.map(p=>p.x*nx+p.y*ny).sort((a,b)=>a-b),threshold=values[Math.floor(values.length*.5)];let groups=[[],[]];d.points.forEach(p=>groups[p.x*nx+p.y*ny<threshold?0:1].push(p));if(groups.some(g=>g.length<8)){result.push(d);continue}for(let i=0;i<2;i++){let points=groups[i],cx=points.reduce((v,p)=>v+p.x,0)/points.length,cy=points.reduce((v,p)=>v+p.y,0)/points.length,rx=cx*c-cy*s,ry=cx*s+cy*c;let centered=points.map(p=>({x:p.x-cx,y:p.y-cy}));let separation=(i?1:-1)*Math.min(70,hit.speed*.12);result.push({...d,x:d.x+rx,y:d.y+ry,vx:d.vx-d.spin*ry+nx*separation,vy:d.vy+d.spin*rx+ny*separation,spin:d.spin+(i?1:-1)*1.5,points:centered,inertia:centered.reduce((v,p)=>v+p.x*p.x+p.y*p.y+2/3,0)/centered.length,generation:(d.generation||0)+1,breakCooldown:.25})}}b.special.debris=result;}

// Immutable shape metadata is rebuilt only when a fragment receives new material points.
function prepareDebris(d){if(d.shapeSource===d.points)return;d.shapeSource=d.points;d.sleeping=false;d.restTime=0;let minX=Infinity,minY=Infinity;for(const p of d.points){minX=Math.min(minX,p.x);minY=Math.min(minY,p.y)}let cells=new Map(),rows=new Map();d.radius=0;for(const p of d.points){let x=Math.round((p.x-minX)/2),y=Math.round((p.y-minY)/2);cells.set(x+','+y,p);if(!rows.has(y))rows.set(y,[]);rows.get(y).push(x);d.radius=Math.max(d.radius,Math.hypot(p.x,p.y)+2)}d.boundary=[];for(const [key,p] of cells){let [x,y]=key.split(',').map(Number);if(!cells.has((x-1)+','+y)||!cells.has((x+1)+','+y)||!cells.has(x+','+(y-1))||!cells.has(x+','+(y+1)))d.boundary.push(p)}d.runs=[];for(const [y,xs] of rows){xs.sort((a,b)=>a-b);let start=xs[0],last=start;for(let i=1;i<=xs.length;i++){if(i<xs.length&&xs[i]===last+1){last=xs[i];continue}d.runs.push({x:minX+start*2-1,y:minY+y*2-1,w:(last-start+1)*2+.05});start=last=xs[i]}}d.cachedPath=typeof Path2D!=='undefined'?new Path2D():null;if(d.cachedPath)for(const r of d.runs)d.cachedPath.rect(r.x,r.y,r.w,2.05);}

function tickMagneticField(b,dt){let f=b.special.magnetField;if(!f)return;f.remaining-=dt;if(f.remaining<=0){b.special.magnetField=null;return}if(b.action||b.special.arena||!f.source||f.source.done)return;let targetCenter=b.x<330?174:486,sourceCenter=f.source.x<330?174:486;let anchorX=targetCenter+(f.source.x-sourceCenter)*.65,anchorY=f.source.y;let dx=anchorX-b.x,dy=anchorY-b.y,distance=Math.hypot(dx,dy),force=cfg.magnetPull*(f.ultimate?1.35:1),falloff=Math.min(1,distance/55);let ax=distance>1?dx/distance*force*falloff:0,ay=distance>1?dy/distance*force*falloff:0;let damp=Math.exp(-cfg.magnetDamping*dt);b.vx=Math.max(-260,Math.min(260,(b.vx+ax*dt)*damp));b.v=Math.max(-600,Math.min(600,(b.v+ay*dt)*damp));}
function drawMagneticField(b){let s=b.special;ctx.save();if(b.role==='magnet'){ctx.fillStyle='#0a071ac9';ctx.beginPath();ctx.arc(b.x,b.y,36,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#c8a7f0';ctx.lineWidth=2;for(let k=0;k<3;k++){ctx.beginPath();ctx.ellipse(b.x,b.y,42+k*5,14+k*4,time*2+k,0,Math.PI*2);ctx.stroke()}ctx.strokeStyle='#eaa2c4';ctx.lineWidth=3;ctx.beginPath();ctx.arc(b.x,b.y,38,-Math.PI/2,-Math.PI/2+Math.PI*2*s.magnetEnergy/100);ctx.stroke()}let f=s.magnetField;if(f){ctx.strokeStyle=f.ultimate?'#f3b2df':'#9ebffc';ctx.lineWidth=1.5;ctx.globalAlpha=.65;for(let k=0;k<2;k++){ctx.beginPath();ctx.ellipse(b.x,b.y,40+k*6,17+k*3,time*2+k,0,Math.PI*2);ctx.stroke()}ctx.font='bold 13px system-ui';ctx.textAlign='center';ctx.fillStyle=ctx.strokeStyle;ctx.fillText(f.ultimate?'± 强磁场':'±',b.x,b.y-47);if(f.source){ctx.globalAlpha=.65;ctx.lineWidth=f.ultimate?3:2;ctx.setLineDash([8,4]);ctx.beginPath();ctx.moveTo(f.source.x,f.source.y);ctx.quadraticCurveTo(330,Math.min(f.source.y,b.y)-45,b.x,b.y);ctx.stroke()}}ctx.restore();}

function drawShockState(b){let s=b.special;ctx.save();if(s.resonanceNotice>0){ctx.globalAlpha=Math.min(1,s.resonanceNotice/.25);ctx.fillStyle='#ffe8a6';ctx.font='bold 18px system-ui';ctx.textAlign='center';ctx.shadowColor='#7e4f12';ctx.shadowBlur=8;ctx.fillText('共振！',b.x,b.y-60-(.9-s.resonanceNotice)*15);ctx.globalAlpha=1;ctx.shadowBlur=0}if(s.stunTime>0){ctx.fillStyle='#ffeeb1';ctx.font='bold 17px system-ui';ctx.textAlign='center';for(let k=0;k<3;k++){let a=time*5+k*Math.PI*2/3;ctx.fillText('✦',b.x+Math.cos(a)*25,b.y-43+Math.sin(a)*5)}ctx.font='12px system-ui';ctx.fillText('昏迷',b.x,b.y-60)}ctx.restore();}

function resonanceProperties(j){let strength=Math.log10(1+levels[j]);return {omega:Math.PI*2*(cfg.resFrequency+.18*(j%3)+.12*strength),damping:cfg.resDamping*(1+.12*(j%4)),limit:cfg.resLimit*(1+.14*strength)}}
function tickResonance(b,dt){if(b.role!=='gyro')return;b.special.resonanceNotice=Math.max(0,b.special.resonanceNotice-dt);b.special.resCooldown=Math.max(0,b.special.resCooldown-dt);b.special.boards.forEach((p,j)=>{let r=p.resonance,properties=resonanceProperties(j);let steps=Math.max(1,Math.ceil(dt/.004)),h=dt/steps;for(let i=0;i<steps;i++){r.velocity+=(-(properties.omega**2)*r.position-properties.damping*2*r.velocity)*h;r.position+=r.velocity*h}r.flash=Math.max(0,r.flash-dt);let amplitude=Math.hypot(r.position,r.velocity/properties.omega)/properties.limit;r.crackClock+=dt;if(amplitude>.12&&r.crackClock>=.065){r.crackClock=0;let stress=Math.min(1,amplitude+r.fatigue);if(r.cracks.length<Math.floor(stress*12)){let x=20+Math.random()*236;r.cracks.push({points:[{x,y:15}],direction:Math.random()<.5?-1:1})}for(const crack of r.cracks){let last=crack.points.at(-1);if(last.x<=2||last.x>=274||crack.points.length>=40)continue;let wave=Math.sin(last.x/276*Math.PI*3+time*properties.omega);crack.points.push({x:Math.max(2,Math.min(274,last.x+crack.direction*(1+stress*3))),y:Math.max(2,Math.min(28,last.y+wave*2.2+(Math.random()-.5)*1.5))})}}})}
function drawResonance(b,j,x,y){if(b.role!=='gyro')return;let r=b.special.boards[j].resonance;ctx.save();let fatigue=Math.min(1,r.fatigue);if(fatigue>.015){ctx.save();ctx.beginPath();ctx.roundRect(x+1,y+1,274,28,4);ctx.clip();ctx.fillStyle='rgba(231,244,246,'+(fatigue*.17)+')';ctx.fillRect(x,y,276,30);let seed=(j+1)*731;const random=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296};for(let k=0;k<Math.floor(fatigue*100);k++){let px=x+8+random()*260,py=y+4+random()*22,len=2+random()*10;ctx.strokeStyle='rgba(244,251,250,'+(.05+fatigue*.24)+')';ctx.lineWidth=.5+random()*.8;ctx.beginPath();ctx.moveTo(px,py);ctx.lineTo(px+len,py+Math.sin(px*.09)*2);ctx.stroke()}for(const crack of r.cracks){if(crack.points.length<2)continue;ctx.beginPath();crack.points.forEach((p,k)=>k?ctx.lineTo(x+p.x,y+p.y):ctx.moveTo(x+p.x,y+p.y));ctx.strokeStyle='rgba(227,245,248,'+(fatigue*.24)+')';ctx.lineWidth=3+fatigue*5;ctx.stroke()}ctx.restore()}let stress=Math.min(1,Math.hypot(r.position,r.velocity/resonanceProperties(j).omega)/resonanceProperties(j).limit+r.fatigue);ctx.strokeStyle=r.flash>.15?'#ffe2a0':'#d5bd7866';ctx.lineWidth=1.5;ctx.beginPath();for(let k=0;k<=30;k++){let px=x+k*9.2,py=y+15+Math.sin(k*.85+time*12)*stress*5;k?ctx.lineTo(px,py):ctx.moveTo(px,py)}ctx.stroke();ctx.strokeStyle='#f0fcff';ctx.lineWidth=.7+fatigue*.8;ctx.globalAlpha=.25+Math.min(1,stress)*.65;for(const crack of r.cracks){ctx.beginPath();crack.points.forEach((p,k)=>k?ctx.lineTo(x+p.x,y+p.y):ctx.moveTo(x+p.x,y+p.y));ctx.stroke()}ctx.restore()}

function tickBending(b,dt){let ratio=1;for(let j=0;j<8;j++){let m=b.special.boards[j].bend;m.pulse=Math.max(0,m.pulse-dt);for(let step=0,n=Math.max(1,Math.ceil(dt/.003));step<n;step++){let h=dt/n;for(let k=1;k<24;k++){let node=m.nodes[k],left=m.nodes[k-1],right=m.nodes[k+1];let force=m.pulse>0?node.load*m.polarity*cfg.bendForce*ratio:0;let stiffness=1+.1*Math.log10(1+levels[j]);let neighbour=0;if(m.links[k-1]<cfg.bendTear)neighbour+=left.y-node.y;if(m.links[k]<cfg.bendTear)neighbour+=right.y-node.y;node.v+=(force-neighbour*-110*stiffness-(node.y-node.rest)*40*stiffness-node.v*8)*h;node.y=Math.max(-55,Math.min(55,node.y+node.v*h));let strain=node.y-node.rest;if(Math.abs(strain)>cfg.bendElastic*cfg.bendResistance)node.rest+=Math.sign(strain)*(Math.abs(strain)-cfg.bendElastic*cfg.bendResistance)*h*2;node.load*=Math.exp(-h*.3)}for(let k=0;k<24;k++){if(!m.present[k])continue;let a=m.nodes[k],z=m.nodes[k+1],strain=Math.abs(z.y-a.y);if(strain>cfg.bendElastic*.18)m.links[k]+=h*(strain-cfg.bendElastic*.18)*.4/(stiffnessForBend(j)*cfg.bendResistance)}}let first=0;while(first<24){if(!m.present[first]){first++;continue}let last=first;while(last<23&&m.present[last+1]&&m.links[last]<cfg.bendTear)last++;let anchored=first===0||last===23;if(!anchored){let cx=(first+last+1)*5.75,cy=0,vy=0;for(let k=first;k<=last;k++){cy+=(m.nodes[k].y+m.nodes[k+1].y)/2+15;vy+=(m.nodes[k].v+m.nodes[k+1].v)/2}let count=last-first+1;cy/=count;vy/=count;let segments=[];for(let k=first;k<=last;k++){m.present[k]=false;segments.push({k,x:k*11.5-cx,a:m.nodes[k].y-cy,z:m.nodes[k+1].y-cy})}let width=count*11.5,spin=(m.nodes[last+1].v-m.nodes[first].v)/Math.max(11.5,width);m.drop.push({x:cx,y:cy,vx:m.polarity*8,vy,angle:0,spin:Math.max(-4,Math.min(4,spin)),segments});}first=last+1}for(let p of m.drop){let previousY=p.y;p.vy+=cfg.gravity*dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.angle+=p.spin*dt;let c=Math.cos(p.angle),sn=Math.sin(p.angle),base=258+j*113.2,lift=0;let samples=[];for(const segment of p.segments)for(const [x,y] of [[segment.x,segment.a+30],[segment.x+11.5,segment.z+30]])samples.push({x:p.x+x*c-y*sn,y:p.y+x*sn+y*c});for(const point of samples){lift=Math.max(lift,base+point.y-1140);if(p.vy<0)continue;for(let next=j+1;next<8;next++){let other=b.special.boards[next].bend,col=Math.floor(point.x/11.5);if(col<0||col>23||!other.present[col])continue;let surface=(next-j)*113.2+(other.nodes[col].y+other.nodes[col+1].y)/2,previous=point.y-(p.y-previousY);if(previous<=surface+2&&point.y>=surface)lift=Math.max(lift,point.y-surface)}}if(lift>0){p.y-=lift;p.vy=0;p.vx*=Math.exp(-8*dt);p.spin*=Math.exp(-12*dt)}if(p.x<0||p.x>276){p.x=Math.max(0,Math.min(276,p.x));p.vx*=-.2}}}}
function stiffnessForBend(j){return 1+.1*Math.log10(1+levels[j])}
function bendPassage(b){let m=b.special.boards[b.index].bend,local=b.x-(b.x<330?36:348);for(let k=Math.max(0,Math.floor((local-32)/11.5));k<=Math.min(23,Math.floor((local+32)/11.5));k++)if(m.present[k])return false;return true}
function drawBending(b,j,x,y){let m=b.special.boards[j].bend;ctx.save();let texture=bendBoardTexture(b,j);for(let k=0;k<24;k++){if(!m.present[k])continue;let a=m.nodes[k],z=m.nodes[k+1],slope=(z.y-a.y)/11.5;if(m.pulse>0&&a.load>.15){ctx.save();ctx.globalAlpha=Math.min(.55,a.load*m.pulse/cfg.bendDuration);ctx.strokeStyle=m.polarity>0?'#f0a4c5':'#9ed5ff';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(x+k*11.5,y+a.y+15);ctx.quadraticCurveTo(x+k*11.5-7,y+a.y+m.polarity*28,x+k*11.5,y+a.y+m.polarity*44);ctx.stroke();ctx.restore()}ctx.save();ctx.translate(x+k*11.5,y+a.y);ctx.transform(1,slope,0,1,0,0);ctx.drawImage(texture,k*11.5,0,11.5,30,0,0,11.5,30);ctx.restore();if(m.links[k]>.2){ctx.strokeStyle='#f3e4f3';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(x+(k+.5)*11.5,y+a.y);ctx.lineTo(x+(k+.6)*11.5,y+a.y+15);ctx.lineTo(x+(k+.4)*11.5,y+a.y+30);ctx.stroke()}}for(const p of m.drop){ctx.save();ctx.translate(x+p.x,y+p.y);ctx.rotate(p.angle);for(const segment of p.segments){ctx.save();ctx.translate(segment.x,segment.a);ctx.transform(1,(segment.z-segment.a)/11.5,0,1,0,0);ctx.drawImage(texture,segment.k*11.5,0,11.5,30,0,0,11.5,30);ctx.restore()}ctx.restore()}ctx.restore();}
function bendBoardTexture(b,j){let m=b.special.boards[j].bend,label=fmt(b.hp[j]);if(m.texture&&m.textureLabel===label)return m.texture;let canvas=document.createElement('canvas');canvas.width=276;canvas.height=30;let g=canvas.getContext('2d');g.fillStyle=themePalettes.neon.boards[j];g.beginPath();g.roundRect(0,0,276,30,6);g.fill();g.strokeStyle='#94e6ee88';g.lineWidth=2;g.stroke();g.strokeStyle='#b3f4fa88';g.lineWidth=1;g.strokeRect(2,2,272,26);g.fillStyle='#c5f3ff17';g.fillRect(4,3,268,6);g.fillStyle='#ffffff44';g.fillRect(4,3,268,5);g.fillStyle='#f0faff';g.font='bold 22px system-ui';g.textAlign='center';g.fillText(label,138,23);m.texture=canvas;m.textureLabel=label;return canvas;}

function logAdd(a,z){if(a===-Infinity)return z;let high=Math.max(a,z),low=Math.min(a,z);return high+Math.log10(1+10**(low-high))}
function assembleScrapBoard(b){let pieces=[],available=0;for(let j=0;j<8;j++)for(const d of b.special.boards[j].bend.drop){available+=d.segments.length;pieces.push({j,d})}let yieldRatio=1-cfg.scrapWaste/100,required=Math.ceil(24/yieldRatio);if(available<required)return false;let target=soloMode?null:lanes.find(o=>o!==b);if(!target||target.done||target.special.scrapBoards.length+b.special.scrapFlights.length>=2)return false;let base=258+Math.min(7,target.index)*113.2,y=base-48;if(y<target.y+70)y=base+113.2-48;if(y>1090)return false;let strength=-Infinity,parts=[],flying=[],budget=required,origin=b.x<330?36:348;for(const piece of pieces){if(!budget)break;let take=Math.min(budget,piece.d.segments.length),share=take/required;strength=logAdd(strength,levels[piece.j]+Math.log10(share*cfg.scrapWeight));parts.push({source:piece.j,count:share*24});let d=piece.d,c=Math.cos(d.angle||0),sn=Math.sin(d.angle||0);for(let n=0;n<Math.min(take,8);n++){let seg=d.segments[n];flying.push({source:piece.j,x:origin+d.x+seg.x*c-seg.a*sn,y:258+piece.j*113.2+d.y+seg.x*sn+seg.a*c,angle:d.angle||0})}piece.d.segments.splice(0,take);budget-=take}for(const p of b.special.boards)p.bend.drop=p.bend.drop.filter(d=>d.segments.length);assemblySound(false);b.special.scrapFlights.push({age:0,target,y,hp:strength,parts,flying,total:24});return true;}
function tickScrapFlights(b,dt){for(const f of b.special.scrapFlights){f.age+=dt;let beat=Math.floor(f.age/.16);if(beat>(f.soundBeat||0)){f.soundBeat=beat;assemblySound(false)}if(f.age>=cfg.scrapFlight&&!f.delivered){let origin=f.target.x<330?36:348;if(f.y<f.target.y+40){let next=258+Math.min(7,f.target.index)*113.2;f.y=next-48;if(f.y<f.target.y+40)f.y=next+113.2-48}f.y=Math.min(1090,f.y);assemblySound(true);f.target.special.scrapBoards.push({y:f.y,hp:f.hp,original:f.hp,parts:f.parts,total:f.total,hits:0});f.delivered=true}}b.special.scrapFlights=b.special.scrapFlights.filter(f=>!f.delivered);}
function drawScrapFlights(b){ctx.save();for(const f of b.special.scrapFlights){let t=Math.min(1,f.age/cfg.scrapFlight),e=t*t*(3-2*t),origin=f.target.x<330?36:348;f.flying.forEach((p,k)=>{let tx=origin+8+(k+.5)/f.flying.length*260,ty=f.y+11,x=p.x+(tx-p.x)*e,y=p.y+(ty-p.y)*e-Math.sin(t*Math.PI)*65;ctx.strokeStyle='#b5d2ff';ctx.globalAlpha=.3*Math.sin(t*Math.PI);ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(b.x,b.y);ctx.quadraticCurveTo((b.x+x)/2,b.y-40,x,y);ctx.stroke();ctx.globalAlpha=1;ctx.save();ctx.translate(x,y);ctx.rotate(p.angle*(1-e)+t*Math.PI*2);ctx.fillStyle=themePalettes.neon.boards[p.source];ctx.fillRect(-7,-5,14,10);ctx.strokeStyle='#d4f6ff88';ctx.strokeRect(-7,-5,14,10);ctx.restore()})}ctx.restore();}
function tickScrapBoard(b,side,dt){if(tickScrapSpecial(b,side,dt))return true;let list=b.special.scrapBoards;if(!list.length)return false;let upward=b.v<0;let travel=b.v*dt+cfg.gravity*dt*dt;let obstacle=list.filter(o=>upward?(b.y-32>=o.y+18&&b.y-32+travel<=o.y+22):(b.y+32<=o.y+4&&b.y+32+travel>=o.y)).sort((a,z)=>Math.abs(a.y-b.y)-Math.abs(z.y-b.y))[0];if(!obstacle)return false;if(b.role==='drill'||b.role==='cube'){ensureScrapState(b,obstacle);b.y=upward?obstacle.y+62:obstacle.y-32;b.action={scrapRef:obstacle,upward,elapsed:0,duration:b.role==='drill'?cfg.drillDuration:cfg.cubeWait,floor:obstacle.y,angle:Math.atan2(b.v,b.vx)};return true}if(b.role==='lead')return false;b.y=upward?obstacle.y+54:obstacle.y-32;let before=obstacle.hp,broken=false,role=b.role;if(['root','cube','ln','chaos'].includes(role)){if(Math.round(10**before)<=1)broken=true;else if(role==='root')obstacle.hp/=cfg.rootDegree;else if(role==='cube')obstacle.hp/=cfg.cubeDegree;else if(role==='ln')obstacle.hp=Math.log10(Math.max(1,before*Math.LN10/Math.log(cfg.lnBase)));else obstacle.hp/=cfg.chaosMin+Math.random()*(cfg.chaosMax-cfg.chaosMin)}else{let fraction=role==='drill'?1/cfg.drillHits:role==='spring'?cfg.springBase/100+cfg.springBonus/100*Math.min(1,(b.v/650)**2):role==='parasite'?cfg.parasiteBase/100:role==='phase'?cfg.phaseBase/100:role==='lead'?.15:.12;let damage=role==='heavy'?b.power+(b.rageTime>0?Math.log10(cfg.rageMultiplier):0):obstacle.original+Math.log10(fraction);if(role==='heavy')b.power+=Math.log10(cfg.growth);if(damage>=before-1e-10||role==='drill'&&Math.random()<cfg.drillChance/100)broken=true;else obstacle.hp=before+Math.log10(1-10**(damage-before))}b.hits++;recordDamage(b,before,broken?null:obstacle.hp);impact(b.x,obstacle.y,'#b4c6d9',side,broken);soundEffect(broken?'break':'hit',role);if(broken){list.splice(list.indexOf(obstacle),1);b.v=upward?-cfg.fall:cfg.fall}else b.v=upward?cfg.bounce:-cfg.bounce;return true;}
function drawScrapBoards(b){let x=b.x<330?36:348;ctx.save();for(const o of b.special.scrapBoards){ctx.save();if(o.state&&b.role==='lead'){ctx.beginPath();for(let row=0;row<15;row++)for(let col=0;col<138;col++)if(o.state.material[row*138+col])ctx.rect(x+col*2,o.y+row*2,2,2);ctx.clip()}if(b.action?.scrapRef===o){ctx.translate(Math.sin(b.action.elapsed*105)*3,Math.sin(b.action.elapsed*137)*2.5)}let offset=0;for(const part of o.parts){let w=276*part.count/o.total;round(x+offset,o.y,w,30,2,themePalettes.neon.boards[part.source],'#c2eaff88');ctx.strokeStyle='#182437';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x+offset,o.y);ctx.lineTo(x+offset+3,o.y+11);ctx.lineTo(x+offset,o.y+22);ctx.stroke();offset+=w}ctx.fillStyle='#fff';ctx.textAlign='center';ctx.font='bold 17px system-ui';ctx.fillText(fmt(o.hp),x+138,o.y+17);ctx.fillStyle='#b2e6e0';ctx.font='10px system-ui';ctx.fillText('拼接板',x+138,o.y-5);if(o.state)withScrapState(b,o,()=>drawDamage(b,0,x,o.y));ctx.restore()}ctx.restore();}

function reflectMagnet(b,vx,vy){let m=b.special.boards[b.index].bend,local=b.x-(b.x<330?36:348),k=Math.max(0,Math.min(23,Math.floor(local/11.5))),slope=(m.nodes[k+1].y-m.nodes[k].y)/11.5,ny=-1/Math.hypot(slope,1),nx=-slope*ny;let surfaceVelocity=(m.nodes[k].v+m.nodes[k+1].v)/2,relativeY=vy-surfaceVelocity,dot=vx*nx+relativeY*ny;let rx=vx-2*dot*nx,ry=relativeY-2*dot*ny,speed=cfg.bounce+Math.random()*cfg.bounceRandom,scale=speed/Math.max(1,Math.hypot(rx,ry));b.vx=rx*scale;b.v=ry*scale+surfaceVelocity*.3;}

function tickMagnetPhysics(b,side,dt){let origin=side?348:36,steps=Math.max(1,Math.ceil(dt/.003));for(let step=0;step<steps;step++){let h=dt/steps;if(b.index<8){let m=b.special.boards[b.index].bend;if(m.focus!==null){m.swingAge+=h;let damage=Math.min(1,Math.max(...m.links)/cfg.bendTear),radius=cfg.magnetSwing*(1-damage*.65),target=origin+m.focus+Math.sin(m.swingAge*Math.PI*2*cfg.magnetSwingRate)*radius;let acceleration=(target-b.x)*cfg.magnetReturn-b.vx*cfg.magnetDrag;b.vx+=acceleration*h;}}b.v+=cfg.gravity*h;b.x+=b.vx*h;b.y+=b.v*h;if(b.x<origin+32){b.x=origin+32;b.vx=Math.abs(b.vx)}if(b.x>origin+244){b.x=origin+244;b.vx=-Math.abs(b.vx)}let best=null;for(let j=0;j<8;j++){let top=258+j*113.2;if(b.y+33<top-55||b.y-33>top+85)continue;let m=b.special.boards[j].bend;for(let k=0;k<24;k++){if(!m.present[k])continue;let x=origin+k*11.5,ya=top+m.nodes[k].y,yz=top+m.nodes[k+1].y;let edges=[[x,ya,x+11.5,yz],[x,ya+30,x+11.5,yz+30]];if(k===0||!m.present[k-1])edges.push([x,ya,x,ya+30]);if(k===23||!m.present[k+1])edges.push([x+11.5,yz,x+11.5,yz+30]);for(const [ax,ay,zx,zy] of edges){let dx=zx-ax,dy=zy-ay,t=Math.max(0,Math.min(1,((b.x-ax)*dx+(b.y-ay)*dy)/(dx*dx+dy*dy||1))),cx=ax+t*dx,cy=ay+t*dy,nx=b.x-cx,ny=b.y-cy,dist=Math.hypot(nx,ny);if(dist>32.5||dist<.001)continue;nx/=dist;ny/=dist;let boardV=(m.nodes[k].v+m.nodes[k+1].v)/2,dot=b.vx*nx+(b.v-boardV)*ny;if(dot>=0)continue;let score=32-dist;if(!best||score>best.score)best={j,nx,ny,dist,dot,boardV,cx,cy,score};}}}if(best){let c=best;b.x+=c.nx*Math.max(0,32.1-c.dist);b.y+=c.ny*Math.max(0,32.1-c.dist);let vx=b.vx-2*c.dot*c.nx,vy=b.v-c.boardV-2*c.dot*c.ny,speed=cfg.bounce+Math.random()*cfg.bounceRandom,scale=speed/Math.max(1,Math.hypot(vx,vy));b.vx=vx*scale;b.v=vy*scale+c.boardV*.3;let progress=b.index;b.index=c.j;newHit(b);b.hits++;impact(c.cx,c.cy,roleOf(b).color,side,false);soundEffect('hit','magnet');b.index=progress;}while(b.index<8&&b.y-32>258+b.index*113.2+85)b.index++;if(b.y+32>=1140&&b.v>0){b.y=1108;b.done=true;b.finish=time;finishRace(side);return}}}

function ensureScrapState(b,o){if(o.state)return;let dummy={role:b.role};initNewBall(dummy);o.state=dummy.special.boards[0];o.fracture={nodes:[],edges:[],tips:[],loads:[],seed:137};}
